import {palette, navigationGroups, canOpen} from './PremiumDashboard';
import React, {useEffect, useMemo, useState} from 'react';
import {Alert, FlatList, Image, Modal, Platform, Pressable, ScrollView, StyleSheet, Text, TextInput, View} from 'react-native';
import {Ionicons} from '@expo/vector-icons';
import * as ImagePicker from 'expo-image-picker';
import {BlurView} from 'expo-blur';
import {LinearGradient} from 'expo-linear-gradient';

const yellow='#f4c430',white='#f7f6ed',muted='#9b9d94',line='rgba(255,255,255,.16)',glass='rgba(31,32,26,.72)';
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(Number(n)||0);
const today=()=>new Date().toISOString().slice(0,10);
const dateKey=value=>{if(!value)return'';const d=new Date(value);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};

export const adminNavigation=[
 ['overview','analytics-outline','Overview'],
 ['tables','grid-outline','Tables'],
 ['bookings','calendar-outline','Table Bookings'],
 ['orders','receipt-outline','Orders & Billing'],
 ['parcels','cube-outline','Parcel Orders'],
 ['menu','fast-food-outline','Food & Photos'],
 ['stock','layers-outline','Stock Management'],
 ['finance','wallet-outline','Finance Management'],
 ['staff','people-outline','Staff'],
 ['settings','settings-outline','Settings'],
];

function Header({kicker,title,copy,action}){return <View style={m.header}><View style={m.flex}><Text style={m.kicker}>{kicker}</Text><Text style={m.title}>{title}</Text>{copy?<Text style={m.copy}>{copy}</Text>:null}</View>{action}</View>}
function IconButton({icon,onPress,danger=false}){return <Pressable style={[m.iconButton,danger&&m.iconDanger]} onPress={onPress}><Ionicons name={icon} size={19} color={danger?'#ff8175':yellow}/></Pressable>}
function Action({title,icon='arrow-forward',onPress,secondary=false,danger=false,disabled=false}){return <Pressable disabled={disabled} style={[m.action,secondary&&m.actionSecondary,danger&&m.actionDanger,disabled&&m.disabled]} onPress={onPress}><Text style={[m.actionText,(secondary||danger)&&m.actionTextLight]}>{title}</Text><Ionicons name={icon} size={17} color={secondary||danger?white:'#15160e'}/></Pressable>}
function Chip({label,active,onPress,tone,disabled=false}){return <Pressable disabled={disabled} onPress={onPress} style={[m.chip,active&&m.chipActive,tone&&{borderColor:tone},disabled&&m.disabled]}><Text style={[m.chipText,active&&m.chipTextActive,disabled&&m.chipTextDisabled]}>{label}</Text></Pressable>}
function Field({label,value,onChangeText,placeholder='',numeric=false,multiline=false}){return <View style={m.field}><Text style={m.fieldLabel}>{label}</Text><TextInput style={[m.input,multiline&&m.textarea]} value={String(value??'')} onChangeText={onChangeText} placeholder={placeholder} placeholderTextColor="#666960" keyboardType={numeric?'decimal-pad':'default'} multiline={multiline}/></View>}
function Sheet({visible,close,title,children,wide=false}){return <Modal visible={visible} transparent animationType="fade" onRequestClose={close}><View style={m.overlay}><View style={[m.sheet,wide&&m.sheetWide]}><View style={m.sheetHead}><Text style={m.sheetTitle}>{title}</Text><IconButton icon="close" onPress={close}/></View><ScrollView keyboardShouldPersistTaps="handled" contentContainerStyle={m.sheetBody}>{children}</ScrollView></View></View></Modal>}
function Empty({icon,title,copy}){return <View style={m.empty}><Ionicons name={icon} size={35} color={muted}/><Text style={m.emptyTitle}>{title}</Text><Text style={m.emptyCopy}>{copy}</Text></View>}
function Status({value}){const color=value==='ready'||value==='paid'||value==='completed'?'#6ec98a':value==='new'||value==='unpaid'?'#efb45c':value==='preparing'?'#6fa7da':'#a9aaa2';return <View style={[m.status,{borderColor:color+'77',backgroundColor:color+'18'}]}><Text style={[m.statusText,{color}]}>{String(value||'—').replace('_',' ')}</Text></View>}
export function OperationsCalendarMobile({orders,kicker,title,copy,onSelect,action}){
 const[month,setMonth]=useState(()=>{const d=new Date();return new Date(d.getFullYear(),d.getMonth(),1)}),year=month.getFullYear(),mi=month.getMonth(),days=new Date(year,mi+1,0).getDate(),leading=new Date(year,mi,1).getDay(),cells=[...Array(leading).fill(null),...Array.from({length:days},(_,i)=>i+1)];while(cells.length%7)cells.push(null);
 const key=day=>`${year}-${String(mi+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;
 return <ScrollView contentContainerStyle={m.page}><Header kicker={kicker} title={title} copy={copy} action={action}/><View style={m.calendarHead}><IconButton icon="chevron-back" onPress={()=>setMonth(new Date(year,mi-1,1))}/><Text style={m.calendarMonth}>{month.toLocaleDateString('en-IN',{month:'long',year:'numeric'})}</Text><IconButton icon="chevron-forward" onPress={()=>setMonth(new Date(year,mi+1,1))}/></View><View style={m.week}>{['S','M','T','W','T','F','S'].map((x,i)=><Text key={`${x}-${i}`} style={m.weekDay}>{x}</Text>)}</View><View style={m.calendar}>{cells.map((day,index)=>{if(!day)return <View key={index} style={m.dayBlank}/>;const daily=orders.filter(x=>dateKey(x.createdAt)===key(day)),paid=daily.filter(x=>x.paymentStatus==='paid'),revenue=paid.reduce((n,x)=>n+Number(x.total||0),0);return <Pressable key={index} onPress={()=>onSelect(key(day))} style={[m.day,key(day)===today()&&m.today,daily.length&&m.dayActive]}><Text style={m.dayNo}>{day}</Text>{daily.length?<><View style={m.dayDot}/><Text style={m.dayAmount}>{daily.length} orders</Text><Text style={m.dayRevenue}>{money(revenue)}</Text></>:null}</Pressable>})}</View></ScrollView>
}
function DrawerGlass(){return <View pointerEvents="none" style={StyleSheet.absoluteFill}><BlurView intensity={58} tint="dark" experimentalBlurMethod={Platform.OS==='android'?'dimezisBlurView':undefined} style={StyleSheet.absoluteFill}/><LinearGradient colors={['rgba(255,255,255,.105)','rgba(25,28,21,.72)','rgba(5,7,4,.88)']} locations={[0,.42,1]} start={{x:0,y:0}} end={{x:1,y:1}} style={StyleSheet.absoluteFill}/><View style={m.drawerAura}/></View>}

export function AdminDrawer({visible,close,current,select,user,logout}){return <Modal visible={visible} transparent animationType="fade" onRequestClose={close}><View style={m.drawerShade}><Pressable style={m.drawer} onPress={()=>{}}><DrawerGlass/><View style={m.drawerTopLine}/><View style={m.drawerBrand}><Image source={require('./assets/knockout-logo.png')} resizeMode="cover" style={m.drawerLogo}/><View><Text style={m.drawerTitle}>KnockOUT</Text><Text style={m.drawerRole}>PROPERTY MANAGEMENT</Text></View></View><ScrollView showsVerticalScrollIndicator={false} contentContainerStyle={m.drawerNav}>{navigationGroups.map(group=><View key={group.title}><Text style={m.navGroupTitle}>{group.title}</Text>{adminNavigation.filter(([id])=>group.ids.includes(id)&&canOpen(id,user)).map(([id,icon,label])=><Pressable key={id} onPress={()=>{select(id);close()}} style={[m.drawerItem,current===id&&m.drawerItemActive]}>{current===id?<LinearGradient colors={['rgba(244,196,48,.2)','rgba(244,196,48,.08)']} start={{x:0,y:0}} end={{x:1,y:1}} style={StyleSheet.absoluteFill}/>:null}<View style={[m.drawerIcon,current===id&&m.drawerIconActive]}><Ionicons name={icon} size={22} color={current===id?yellow:'#a5a89f'}/></View><Text style={[m.drawerLabel,current===id&&m.drawerLabelActive]}>{label}</Text>{current===id?<View style={m.drawerDot}/>:null}</Pressable>)}</View>)}</ScrollView><View style={m.drawerUser}><LinearGradient colors={['rgba(255,255,255,.12)','rgba(255,255,255,.035)']} style={StyleSheet.absoluteFill}/><LinearGradient colors={['#f2ce70','#c99b3f']} style={m.drawerAvatar}><Text style={m.drawerAvatarText}>{user.name.split(' ').map(x=>x[0]).join('').slice(0,2)}</Text></LinearGradient><View style={m.flex}><Text style={m.drawerUserName}>{user.name}</Text><Text style={m.drawerUserRole}>Administrator</Text></View></View></Pressable><View style={m.drawerRail}><Pressable style={m.drawerSideAction} onPress={logout}><Ionicons name="log-out-outline" size={24} color="#a7aaa1"/></Pressable><Pressable style={m.drawerRailClose} onPress={close}/></View></View></Modal>}

export function AdminBookings({state,refresh,notify,request}){
 const[selectedDate,setSelectedDate]=useState(null),[creating,setCreating]=useState(false),[month,setMonth]=useState(()=>{const d=new Date();return new Date(d.getFullYear(),d.getMonth(),1)}),bookings=state.bookings||[];
 const year=month.getFullYear(),mi=month.getMonth(),days=new Date(year,mi+1,0).getDate(),leading=new Date(year,mi,1).getDay(),cells=[...Array(leading).fill(null),...Array.from({length:days},(_,i)=>i+1)];while(cells.length%7)cells.push(null);
 const key=day=>`${year}-${String(mi+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`,daily=selectedDate?bookings.filter(x=>x.bookingDate===selectedDate):[];
 const cancel=item=>Alert.alert(`Cancel Table ${item.tableNumber}?`,'This releases the reserved time slot.',[{text:'Keep booking',style:'cancel'},{text:'Cancel booking',style:'destructive',onPress:async()=>{try{await request(`/bookings/${item.id}`,{method:'DELETE'});await refresh();notify('Booking cancelled')}catch(e){notify(e.message)}}}]);
 if(selectedDate)return <><FlatList data={daily} keyExtractor={x=>String(x.id)} contentContainerStyle={m.page} ListHeaderComponent={<Header kicker="RESERVATION SCHEDULE" title={selectedDate.split('-').reverse().join('-')} copy={`${daily.length} confirmed bookings for this date.`} action={<IconButton icon="add" onPress={()=>setCreating(true)}/>}/>} ListEmptyComponent={<Empty icon="calendar-outline" title="No bookings" copy="Use + to lock a table and time."/>} renderItem={({item})=><View style={m.card}><View style={m.row}><View><Text style={m.cardEyebrow}>CONFIRMED TABLE</Text><Text style={m.cardTitle}>Table {item.tableNumber}</Text></View><Status value="confirmed"/></View><Text style={m.itemName}>{item.area} · {item.seats} seats</Text><Text style={m.meta}>{item.customerPhone}</Text><View style={m.divider}/><View style={m.row}><View><Text style={m.meta}>RESERVATION TIME</Text><Text style={m.amount}>{item.bookingTime}</Text></View><View><Text style={m.meta}>DURATION</Text><Text style={m.amount}>{item.durationMinutes} min</Text></View></View><View style={m.row}><Text style={m.meta}>SMS: {item.notificationStatus}</Text><IconButton icon="trash-outline" danger onPress={()=>cancel(item)}/></View></View>}/><Action title="Back to calendar" icon="calendar-outline" secondary onPress={()=>setSelectedDate(null)}/>{creating?<AdminBookingEditor state={state} initialDate={selectedDate} refresh={refresh} notify={notify} request={request} close={()=>setCreating(false)}/>:null}</>;
 return <ScrollView contentContainerStyle={m.page}><Header kicker="RESERVATION CALENDAR" title="Table Bookings" copy="Select a date to view or create locked table slots."/><View style={m.calendarHead}><IconButton icon="chevron-back" onPress={()=>setMonth(new Date(year,mi-1,1))}/><Text style={m.calendarMonth}>{month.toLocaleDateString('en-IN',{month:'long',year:'numeric'})}</Text><IconButton icon="chevron-forward" onPress={()=>setMonth(new Date(year,mi+1,1))}/></View><View style={m.week}>{['S','M','T','W','T','F','S'].map((x,i)=><Text key={`${x}-${i}`} style={m.weekDay}>{x}</Text>)}</View><View style={m.calendar}>{cells.map((day,index)=>day?<Pressable key={index} onPress={()=>setSelectedDate(key(day))} style={[m.day,key(day)===today()&&m.today]}><Text style={m.dayNo}>{day}</Text>{bookings.some(x=>x.bookingDate===key(day))?<><View style={m.dayDot}/><Text style={m.dayAmount}>{bookings.filter(x=>x.bookingDate===key(day)).length} booked</Text></>:null}</Pressable>:<View key={index} style={m.dayBlank}/>)}</View></ScrollView>;
}
function AdminBookingEditor({state,initialDate,refresh,notify,request,close}){
 const[tableId,setTableId]=useState(null),[customerPhone,setPhone]=useState(''),[bookingDate,setDate]=useState(initialDate||today()),[bookingTime,setTime]=useState('18:00'),[durationMinutes,setDuration]=useState(90),[busy,setBusy]=useState(false),bookings=state.bookings||[],toMinutes=value=>{const[h,mn]=String(value).split(':').map(Number);return h*60+mn},start=toMinutes(bookingTime),end=start+durationMinutes;
 const locked=id=>bookings.some(x=>x.tableId===id&&x.bookingDate===bookingDate&&toMinutes(x.bookingTime)<end&&toMinutes(x.bookingTime)+Number(x.durationMinutes)>start);
 async function save(){setBusy(true);try{const result=await request('/bookings',{method:'POST',body:JSON.stringify({tableId,customerPhone,bookingDate,bookingTime,durationMinutes})});await refresh();notify(result.notificationStatus==='sent'?'Booking confirmed · SMS sent':'Booking confirmed · SMS queued');close()}catch(e){notify(e.message)}finally{setBusy(false)}}
 return <Sheet visible close={close} title="Book a table"><Text style={m.sheetCopy}>The selected time is locked for Admin and Waiter. A confirmation is sent to the customer number.</Text><Field label="Customer mobile number" value={customerPhone} onChangeText={setPhone} placeholder="+91 7904951736"/><Field label="Booking date (YYYY-MM-DD)" value={bookingDate} onChangeText={value=>{setDate(value);setTableId(null)}}/><Field label="Booking time (24-hour HH:MM)" value={bookingTime} onChangeText={value=>{setTime(value);setTableId(null)}}/><Text style={m.fieldLabel}>DURATION</Text><View style={m.chips}>{[60,90,120,150,180].map(value=><Chip key={value} label={`${value} min`} active={durationMinutes===value} onPress={()=>{setDuration(value);setTableId(null)}}/>)}</View><Text style={m.fieldLabel}>AVAILABLE TABLE FOR THIS SLOT</Text><View style={m.chips}>{state.tables.map(item=><Chip key={item.id} label={`Table ${item.number}${locked(item.id)?' · locked':''}`} active={tableId===item.id} disabled={locked(item.id)} onPress={()=>setTableId(item.id)}/>)}</View><Action title={busy?'Locking…':'Confirm & send SMS'} icon="calendar-outline" onPress={save} disabled={busy||!tableId||!customerPhone||!bookingDate||!bookingTime}/></Sheet>;
}

function AdminParcelsDay({state,refresh,notify,user,request}){const[creating,setCreating]=useState(false),[paying,setPaying]=useState(null),parcels=state.orders.filter(x=>x.orderType==='parcel');async function finish(order,method){try{await request(`/orders/${order.id}/finalize`,{method:'POST',body:JSON.stringify({paymentMethod:method})});await refresh();notify(`Parcel #${order.id} completed`);setPaying(null)}catch(e){notify(e.message)}}async function markPaid(order,method){try{await request(`/orders/${order.id}/mark-paid`,{method:'POST',body:JSON.stringify({paymentMethod:method})});await refresh();notify(`Parcel #${order.id} marked paid`)}catch(e){notify(e.message)}}return <><FlatList data={parcels} keyExtractor={x=>String(x.id)} contentContainerStyle={m.page} ListHeaderComponent={<Header kicker="DAILY PARCEL REGISTER" title="Parcel Orders" copy="Orders, kitchen progress, payment and handoff for the selected date." action={<IconButton icon="add" onPress={()=>setCreating(true)}/>}/>} ListEmptyComponent={<Empty icon="cube-outline" title="No parcel orders" copy="Create the first takeaway order from Admin."/>} renderItem={({item})=>{const total=item.total||item.items.reduce((sum,x)=>sum+(state.menu.find(y=>y.id===x.menuId)?.price||0)*x.qty,0),ready=['ready','served'].includes(item.status);return <View style={m.card}><View style={m.row}><View><Text style={m.cardEyebrow}>PARCEL</Text><Text style={m.cardTitle}>#{item.id}</Text></View><Status value={item.status}/></View><Text style={m.itemName}>{item.guestName}</Text><Text style={m.meta}>{item.customerPhone||'No phone'} · {item.items.reduce((a,x)=>a+x.qty,0)} items</Text><View style={m.divider}/><View style={m.row}><Status value={item.paymentStatus}/><Text style={m.amount}>{money(total)}</Text></View>{item.status!=='completed'&&item.paymentStatus!=='paid'?<View style={m.two}><Action title="Mark Cash paid" secondary onPress={()=>markPaid(item,'Cash')}/><Action title="Mark UPI paid" secondary onPress={()=>markPaid(item,'Card / UPI')}/></View>:null}{ready&&item.status!=='completed'?<Action title={item.paymentStatus==='paid'?'Complete — already paid':'Complete parcel'} icon="checkmark-circle-outline" onPress={()=>item.paymentStatus==='paid'?finish(item):setPaying(item)}/>:null}</View>}}/>{creating?<ParcelEditor state={state} user={user} request={request} close={()=>setCreating(false)} refresh={refresh} notify={notify}/>:null}<Sheet visible={!!paying} close={()=>setPaying(null)} title={`Complete parcel #${paying?.id||''}`}><Text style={m.sheetCopy}>Choose the payment received while handing the parcel to the customer.</Text><Action title="Cash" icon="cash-outline" onPress={()=>finish(paying,'Cash')}/><Action title="Card / UPI" icon="card-outline" secondary onPress={()=>finish(paying,'Card / UPI')}/></Sheet></>}

export function AdminOrders({state}){
 const[selectedDate,setSelectedDate]=useState(null),orders=state.orders||[],daily=selectedDate?orders.filter(x=>dateKey(x.createdAt)===selectedDate):[];
 if(!selectedDate)return <OperationsCalendarMobile orders={orders} kicker="SALES & SERVICE" title="Orders & Billing" copy="Select a date to view dine-in and parcel orders, bills and payments." onSelect={setSelectedDate}/>;
 return <View style={m.flex}><View style={m.calendarBack}><Action title={`Calendar · ${selectedDate.split('-').reverse().join('-')}`} icon="calendar-outline" secondary onPress={()=>setSelectedDate(null)}/></View><FlatList data={daily} keyExtractor={x=>String(x.id)} contentContainerStyle={m.page} ListEmptyComponent={<Empty icon="receipt-outline" title="No orders" copy="There are no orders for this date."/>} renderItem={({item})=>{const table=state.tables.find(x=>x.id===item.tableId),total=item.total||item.items.reduce((sum,x)=>sum+(state.menu.find(y=>y.id===x.menuId)?.price||0)*x.qty,0);return <View style={m.card}><View style={m.row}><View><Text style={m.cardEyebrow}>{item.orderType==='parcel'?'PARCEL':`TABLE ${table?.number||'—'}`}</Text><Text style={m.cardTitle}>#{item.id}</Text></View><Status value={item.status}/></View><Text style={m.itemName}>{item.guestName||'Walk-in Guest'}</Text><Text style={m.meta}>{item.waiter||'Admin'} · {new Date(item.createdAt).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})}</Text><View style={m.divider}/>{item.items.map((line,index)=><View style={m.orderItem} key={`${line.menuId}-${index}`}><Text style={m.orderQty}>{line.qty}×</Text><Text style={m.itemName}>{state.menu.find(x=>x.id===line.menuId)?.name||'Menu item'}</Text></View>)}<View style={m.divider}/><View style={m.row}><Status value={item.paymentStatus}/><Text style={m.amount}>{money(total)}</Text></View></View>}}/></View>
}

export function AdminParcels(props){
 const[selectedDate,setSelectedDate]=useState(null),all=props.state.orders.filter(x=>x.orderType==='parcel');
 if(!selectedDate)return <OperationsCalendarMobile orders={all} kicker="TAKEAWAY OPERATIONS" title="Parcel Orders" copy="Select a date to view parcel orders, payment and kitchen progress." onSelect={setSelectedDate}/>;
 const state={...props.state,orders:all.filter(x=>dateKey(x.createdAt)===selectedDate)};
 return <View style={m.flex}><View style={m.calendarBack}><Action title={`Calendar · ${selectedDate.split('-').reverse().join('-')}`} icon="calendar-outline" secondary onPress={()=>setSelectedDate(null)}/></View><AdminParcelsDay {...props} state={state}/></View>
}

function ParcelEditor({state,user,request,close,refresh,notify}){const[name,setName]=useState(''),[phone,setPhone]=useState(''),[payment,setPayment]=useState('unpaid'),[items,setItems]=useState([]),[busy,setBusy]=useState(false);const add=id=>setItems(old=>{const hit=old.find(x=>x.menuId===id);return hit?old.map(x=>x.menuId===id?{...x,qty:x.qty+1}:x):[...old,{menuId:id,qty:1,note:''}]});const remove=id=>setItems(old=>old.flatMap(x=>x.menuId===id?(x.qty>1?[{...x,qty:x.qty-1}]:[]):[x]));async function save(){setBusy(true);try{await request('/parcels',{method:'POST',body:JSON.stringify({customerName:name,customerPhone:phone,adminName:user.name,items,paymentMethod:payment==='unpaid'?null:payment})});await refresh();notify('Parcel sent to kitchen');close()}catch(e){notify(e.message)}finally{setBusy(false)}}return <Sheet visible close={close} title="New parcel order" wide><Field label="Customer name" value={name} onChangeText={setName}/><Field label="Phone" value={phone} onChangeText={setPhone}/><Text style={m.fieldLabel}>PAYMENT</Text><View style={m.chips}><Chip label="Pay later" active={payment==='unpaid'} onPress={()=>setPayment('unpaid')}/><Chip label="Cash paid" active={payment==='Cash'} onPress={()=>setPayment('Cash')}/><Chip label="Card / UPI" active={payment==='Card / UPI'} onPress={()=>setPayment('Card / UPI')}/></View><Text style={m.section}>SELECT FOOD</Text>{state.menu.map(item=>{const qty=items.find(x=>x.menuId===item.id)?.qty||0;return <View style={[m.menuLine,!item.available&&m.menuLineUnavailable]} key={item.id}><Text style={m.foodIcon}>{item.icon}</Text><View style={m.flex}><Text style={m.itemName}>{item.name}</Text><Text style={[m.meta,!item.available&&m.unavailableText]}>{item.available?`${money(item.price)} · ${item.category}`:`${item.category} · NOT AVAILABLE`}</Text></View>{item.available?<><IconButton icon="remove" onPress={()=>remove(item.id)}/><Text style={m.qty}>{qty}</Text><IconButton icon="add" onPress={()=>add(item.id)}/></>:<Status value="not available"/>}</View>})}<Action title={busy?'Creating…':'Send to kitchen'} icon="paper-plane-outline" onPress={save} disabled={busy||!name||!items.length}/></Sheet>}

export function AdminMenuManager({state,refresh,notify,request,uploadImage}){const[editing,setEditing]=useState(null);async function hide(item){try{await request(`/menu/${item.id}`,{method:'DELETE'});await refresh();notify(`${item.name} hidden`)}catch(e){notify(e.message)}}return <><FlatList data={state.menu} keyExtractor={x=>String(x.id)} contentContainerStyle={m.page} ListHeaderComponent={<Header kicker="MENU ASSET LIBRARY" title="Food & Photos" copy="Add dishes, upload photos, set prices and build customizable combos." action={<IconButton icon="add" onPress={()=>setEditing({})}/>}/>} renderItem={({item})=><Pressable style={m.menuCard} onPress={()=>setEditing(item)}>{item.imageUrl?<Image source={{uri:item.imageUrl}} style={m.foodImage}/>:<View style={m.foodImageFallback}><Text style={m.foodEmoji}>{item.icon}</Text></View>}<View style={m.menuCardBody}><View style={m.row}><View style={m.flex}><Text style={m.itemName}>{item.name}</Text><Text style={m.meta}>{item.category}{item.isCombo?' · Combo':''}</Text></View><Text style={m.amount}>{money(item.price)}</Text></View><View style={m.row}><Status value={item.available?'available':'hidden'}/><IconButton icon="eye-off-outline" danger onPress={()=>hide(item)}/></View></View></Pressable>}/>{editing?<MenuEditor item={editing.id?editing:null} state={state} request={request} uploadImage={uploadImage} refresh={refresh} notify={notify} close={()=>setEditing(null)}/>:null}</>}

