 const[editing,setEditing]=useState(null),[moving,setMoving]=useState(null),[view,setView]=useState('inventory'),[query,setQuery]=useState(''),inventory=state.inventory||[],transactions=state.inventoryTransactions||[],low=inventory.filter(x=>x.quantity<=x.min),cutoff=Date.now()-30*86400000,recent=transactions.filter(x=>new Date(x.createdAt).getTime()>=cutoff),usageCost=recent.filter(x=>x.movementType==='usage').reduce((n,x)=>n+Math.abs(x.quantity)*(x.unitCost||0),0),wasteCost=recent.filter(x=>x.movementType==='waste').reduce((n,x)=>n+Math.abs(x.quantity)*(x.unitCost||0),0),value=inventory.reduce((n,x)=>n+x.quantity*x.cost,0),planning=inventory.map(item=>{const consumed=recent.filter(x=>x.inventoryId===item.id&&['usage','waste'].includes(x.movementType)).reduce((n,x)=>n+Math.abs(x.quantity),0),daily=consumed/30,days=daily?item.quantity/daily:null,reorder=Math.max(0,item.min*2-item.quantity);return{...item,consumed,days,reorder,reorderCost:reorder*item.cost}}).filter(x=>x.quantity<=x.min||(x.days!==null&&x.days<=7)).sort((a,b)=>(a.days??9999)-(b.days??9999)),shown=inventory.filter(x=>`${x.name} ${x.category}`.toLowerCase().includes(query.toLowerCase()));
