export function AdminPeople({state,refresh,notify,request}){const[staff,setStaff]=useState(null),[chef,setChef]=useState(null),[mode,setMode]=useState('accounts'),attendance=state.attendance||[],data=mode==='accounts'?(state.users||[]):(state.kitchenStaff||[]);return <><FlatList data={data} keyExtractor={x=>`${mode}-${x.id}`} contentContainerStyle={m.page} ListHeaderComponent={<><Header kicker="PEOPLE & ATTENDANCE" title="Staff Management" copy="Manage portal logins, attendance and the kitchen team." action={<IconButton icon="person-add-outline" onPress={()=>mode==='accounts'?setStaff({}):setChef({})}/>}/><View style={m.chips}><Chip label="Portal accounts" active={mode==='accounts'} onPress={()=>setMode('accounts')}/><Chip label="Kitchen team" active={mode==='kitchen'} onPress={()=>setMode('kitchen')}/></View></>} renderItem={({item})=>{const shift=mode==='accounts'&&attendance.find(x=>x.userId===item.id&&!x.checkOut);return <Pressable style={m.staffCard} onPress={()=>mode==='accounts'?setStaff(item):setChef(item)}><View style={m.avatar}><Text style={m.avatarText}>{item.name.split(' ').map(x=>x[0]).join('').slice(0,2)}</Text></View><View style={m.flex}><Text style={m.itemName}>{item.name}</Text><Text style={m.meta}>{mode==='accounts'?`${item.role} · PIN ${item.pin}`:`${item.designation} · ${item.specialization||'General kitchen'}`}</Text><Text style={m.meta}>{item.phone||'No phone'} · {money(item.payRate)} / {item.payType}</Text></View>{mode==='accounts'?<View style={[m.dutyDot,{backgroundColor:shift?'#69ca88':'#66685f'}]}/>:<Status value={item.active?'active':'inactive'}/>}</Pressable>}}/>{staff?<StaffEditor item={staff.id?staff:null} request={request} close={()=>setStaff(null)} refresh={refresh} notify={notify}/>:null}{chef?<ChefEditor item={chef.id?chef:null} request={request} close={()=>setChef(null)} refresh={refresh} notify={notify}/>:null}</>}
function StaffEditor({item,request,close,refresh,notify}){
 const[form,setForm]=useState(item?{name:item.name,role:item.role,pin:item.pin,phone:item.phone||'',payType:item.payType,payRate:item.payRate,active:item.active}:{name:'',role:'waiter',pin:'',phone:'',payType:'monthly',payRate:'0',active:true}),[busy,setBusy]=useState(false),[deleteArmed,setDeleteArmed]=useState(false),[accounts,setAccounts]=useState([]),patch=(k,v)=>setForm(x=>({...x,[k]:v}));
 useEffect(()=>{request('/state').then(value=>setAccounts(value.users||[])).catch(()=>{})},[request]);
 const unavailable=role=>['admin','chef','juicer'].includes(role)&&accounts.some(account=>account.role===role&&account.id!==item?.id);
 async function save(){setBusy(true);try{await request(item?`/staff/${item.id}`:'/staff',{method:item?'PUT':'POST',body:JSON.stringify(form)});await refresh();notify('Staff account saved');close()}catch(e){notify(e.message)}finally{setBusy(false)}}
 async function remove(){setBusy(true);try{await request(`/staff/${item.id}`,{method:'DELETE'});await refresh();notify(`${item.name} removed · PIN is available again`);close()}catch(e){notify(e.message)}finally{setBusy(false)}}
 const roles=[['waiter','Waiter'],['chef','Head Chef'],['admin','Admin'],...(item?.role==='juicer'?[['juicer','Juicer']]:[])];
 return <Sheet visible close={close} title={item?'Edit staff login':'Add staff login'}><Field label="Full name" value={form.name} onChangeText={v=>patch('name',v)}/><Text style={m.fieldLabel}>DESIGNATION</Text><View style={m.chips}>{roles.map(([value,label])=><Chip key={value} label={unavailable(value)?`${label} · created`:label} active={form.role===value} disabled={unavailable(value)} onPress={()=>patch('role',value)}/>)}</View><Field label="Unique 6-digit PIN" value={form.pin} onChangeText={v=>patch('pin',v.replace(/\D/g,'').slice(0,6))} numeric/><Field label="Phone" value={form.phone} onChangeText={v=>patch('phone',v)}/><Text style={m.fieldLabel}>SALARY BASIS</Text><View style={m.chips}><Chip label="Daily" active={form.payType==='daily'} onPress={()=>patch('payType','daily')}/><Chip label="Monthly" active={form.payType==='monthly'} onPress={()=>patch('payType','monthly')}/></View><Field label={form.payType==='daily'?'Daily salary amount':'Monthly salary amount'} value={form.payRate} onChangeText={v=>patch('payRate',v)} numeric/><Action title={busy?'Saving…':'Save staff login'} onPress={save} disabled={busy||!form.name||String(form.pin).length!==6||unavailable(form.role)}/>{item&&item.role!=='admin'&&!deleteArmed?<Action title="Delete staff" icon="trash-outline" danger onPress={()=>setDeleteArmed(true)} disabled={busy}/>:null}{item&&item.role!=='admin'&&deleteArmed?<View style={[m.card,m.warningCard]}><Text style={m.itemName}>Permanently remove {item.name}?</Text><Text style={m.meta}>Their login will stop immediately and the six-digit PIN can be reused. Existing attendance history will be preserved.</Text><View style={m.two}><Action title="Cancel" icon="close" secondary onPress={()=>setDeleteArmed(false)} disabled={busy}/><Action title={busy?'Deleting…':'Confirm delete'} icon="trash-outline" danger onPress={remove} disabled={busy}/></View></View>:null}{item&&item.role==='admin'?<View style={m.card}><Text style={m.itemName}>Protected account</Text><Text style={m.meta}>The primary Admin login cannot be deleted.</Text></View>:null}</Sheet>
}
function ChefEditor({item,request,close,refresh,notify}){
 const[form,setForm]=useState(item?{name:item.name,designation:item.designation,phone:item.phone||'',specialization:item.specialization||'',payType:item.payType,payRate:item.payRate,joinedOn:dateKey(item.joinedOn),notes:item.notes||'',active:item.active}:{name:'',designation:'Chef',phone:'',specialization:'',payType:'monthly',payRate:'0',joinedOn:today(),notes:'',active:true}),[busy,setBusy]=useState(false),patch=(k,v)=>setForm(x=>({...x,[k]:v}));async function save(){setBusy(true);try{await request(item?`/kitchen-staff/${item.id}`:'/kitchen-staff',{method:item?'PUT':'POST',body:JSON.stringify(form)});await refresh();notify('Chef details saved');close()}catch(e){notify(e.message)}finally{setBusy(false)}}return <Sheet visible close={close} title={item?'Edit chef':'Add chef'}><Field label="Full name" value={form.name} onChangeText={v=>patch('name',v)}/><Field label="Designation" value={form.designation} onChangeText={v=>patch('designation',v)}/><Field label="Specialization" value={form.specialization} onChangeText={v=>patch('specialization',v)}/><Field label="Phone" value={form.phone} onChangeText={v=>patch('phone',v)}/><Field label="Joining date (YYYY-MM-DD)" value={form.joinedOn} onChangeText={v=>patch('joinedOn',v)}/><Text style={m.fieldLabel}>SALARY BASIS</Text><View style={m.chips}><Chip label="Daily" active={form.payType==='daily'} onPress={()=>patch('payType','daily')}/><Chip label="Monthly" active={form.payType==='monthly'} onPress={()=>patch('payType','monthly')}/></View><Field label={form.payType==='daily'?'Daily salary amount':'Monthly salary amount'} value={form.payRate} onChangeText={v=>patch('payRate',v)} numeric/><Field label="Notes" value={form.notes} onChangeText={v=>patch('notes',v)} multiline/><Action title={busy?'Saving…':'Save chef'} onPress={save} disabled={busy||!form.name||!form.designation}/></Sheet>
}

export function AdminSettings({state,refresh,notify,request}){const[form,setForm]=useState({...state.settings}),[busy,setBusy]=useState(false),patch=(k,v)=>setForm(x=>({...x,[k]:v}));async function save(){setBusy(true);try{await request('/settings',{method:'PUT',body:JSON.stringify(form)});await refresh();notify('Business settings saved')}catch(e){notify(e.message)}finally{setBusy(false)}}return <ScrollView contentContainerStyle={m.page}><Header kicker="ADMIN SETTINGS" title="Business & Billing" copy="Configuration shared instantly by Admin, Waiter and Chef."/><View style={m.card}><Field label="Business name" value={form.hotelName} onChangeText={v=>patch('hotelName',v)}/><Field label="Currency" value={form.currency} onChangeText={v=>patch('currency',v)}/><Field label="GST rate (%)" value={form.taxRate} onChangeText={v=>patch('taxRate',v)} numeric/><Field label="CGST rate (%)" value={form.cgstRate} onChangeText={v=>patch('cgstRate',v)} numeric/><Field label="Service tax (%)" value={form.serviceCharge} onChangeText={v=>patch('serviceCharge',v)} numeric/><Action title={busy?'Saving…':'Save changes'} icon="save-outline" onPress={save} disabled={busy||!form.hotelName}/></View><View style={m.card}><Text style={m.cardEyebrow}>CONNECTED COMPANY DATABASE</Text><Text style={m.cardTitle}>{state.companyDatabase}</Text><Text style={m.meta}>All mobile and web changes are synchronized through this tenant database.</Text></View></ScrollView>}

